const prompt = $json.data;
const ctx = $('Prepare Get-Prompt Input').first().json._ctx;
const model = (prompt.model_compatibility && prompt.model_compatibility[0]) || 'claude-opus-4-8';
const userPayload = {
  topic: ctx.topic, intended_angle: ctx.intended_angle || null,
  channel_niche: ctx.niche || null, target_audience: ctx.target_audience || null,
  target_duration_seconds: ctx.target_duration_seconds || null,
  default_minimum_source_count: ctx.minimum_source_count_override || 5
};
const schema = {"title":"Research Plan","description":"Structured output of the research-planning LLM call, validated before being persisted by upsert_research_plan(). The plan identifies what to look for — it must never invent facts, statistics, or sources; those come later from real search results. Stored in research_plans.plan. See docs/architecture/research-pipeline.md#research-plan.","type":"object","additionalProperties":false,"required":["primary_question","subquestions","important_entities","likely_primary_sources","time_sensitive_facts_to_verify","opposing_viewpoints","minimum_source_count","source_diversity_requirements","expected_source_types"],"properties":{"primary_question":{"type":"string"},"subquestions":{"type":"array","items":{"type":"string"},"minItems":1},"important_entities":{"type":"array","items":{"type":"string"}},"likely_primary_sources":{"type":"array","description":"Descriptions of where a primary source plausibly exists (e.g. 'company Q3 earnings filing'), not actual URLs — the plan does not fabricate sources.","items":{"type":"string"}},"time_sensitive_facts_to_verify":{"type":"array","items":{"type":"string"}},"opposing_viewpoints":{"type":"array","description":"Known or expected points of disagreement worth searching both sides of, where the topic reasonably has any.","items":{"type":"string"}},"minimum_source_count":{"type":"integer"},"source_diversity_requirements":{"type":"object","additionalProperties":false,"required":["minimum_authoritative_sources","require_primary_source"],"properties":{"minimum_authoritative_sources":{"type":"integer"},"require_primary_source":{"type":"boolean"}}},"expected_source_types":{"type":"array","items":{"type":"string","enum":["primary_source","government","academic","official_company","industry_report","reputable_news","expert_analysis","documentation","forum_community","social_media","unknown"]},"minItems":1}}};
return [{ json: {
  ctx, model,
  requestBody: {
    model, max_tokens: 4096,
    system: prompt.content,
    messages: [{ role: 'user', content: JSON.stringify(userPayload) }],
    output_config: { format: { type: 'json_schema', schema } }
  }
} }];

const resp = $input.first().json;
const ctx = $('Prepare Anthropic Request').first().json.ctx;
const model = $('Prepare Anthropic Request').first().json.model;
const textBlock = (resp.content || []).find((b) => b.type === 'text');
let plan = null; let parse_failed = true;
if (textBlock) { try { plan = JSON.parse(textBlock.text); parse_failed = false; } catch (e) { parse_failed = true; } }
return [{ json: { parse_failed, ctx, model, plan, usage: resp.usage || {}, provider_request_id: resp.id || null } }];

const ctx = $json.ctx;
return [{ json: {
  success: false, data: null,
  error: { code: 'CLAIM_EXTRACTION_FAILED', message: 'research plan LLM response was not valid structured JSON after retries', retryable: true, error_id: null },
  runtime: { channel_id: ctx.channel_id, workflow_run_id: ctx.workflow_run_id, content_project_id: ctx.content_project_id, correlation_id: null }
} }];

const j = $('Parse Plan Response').first().json; const ctx = j.ctx;
// Pricing: $5.00 / 1M input tokens, $25.00 / 1M output tokens.
// One multiply-and-divide per call, not a compounding ledger -- every
// persistent aggregate (SUM() over cost_events.total_cost_usd, a NUMERIC
// column) happens in SQL, never in JS. See
// docs/architecture/research-pipeline.md#cost-tracking.
const inputTokens = j.usage.input_tokens || 0;
const outputTokens = j.usage.output_tokens || 0;
const inputCost = (inputTokens / 1000000) * 5;
const outputCost = (outputTokens / 1000000) * 25;
const totalCost = Math.round((inputCost + outputCost) * 1000000) / 1000000;
return [{ json: {
  channel_id: ctx.channel_id, content_project_id: ctx.content_project_id, workflow_run_id: ctx.workflow_run_id, workflow_step_id: null,
  provider: 'anthropic', service_type: 'llm', model: j.model,
  quantity: inputTokens + outputTokens, unit: 'token', unit_price_usd: null,
  total_cost_usd: totalCost, provider_request_id: j.provider_request_id, estimated: false, metadata: {}
} }];
